const out = [];
for (const item of $input.all()) {
  let raw = '';
  const bin = item.binary && item.binary.data ? item.binary.data : null;
  if (bin && typeof bin.data === 'string') {
    raw = Buffer.from(bin.data, 'base64').toString('utf8');
  } else if (typeof item.json.rawBody === 'string') {
    raw = item.json.rawBody;
  }
  out.push({ json: { ...item.json, rawBody: raw }, binary: item.binary });
}
return out;

const root = $('HCP Webhook').item.json;
const body = root.body || root;
const ev = body.event || '';
const c = body.customer || {};

const customer_id   = (c.id != null) ? String(c.id) : '';
const customer_first = String(c.first_name || '').trim();
const customer_last  = String(c.last_name  || '').trim();
const customer_email = String(c.email || '').trim();
const customer_phone = String(c.mobile_number || c.home_number || c.work_number || '').trim();
const lead_source    = String(c.lead_source || '').trim();
const tags = Array.isArray(c.tags) ? c.tags : [];

// EXACT (case-insensitive) vertical-tag resolver. Returns null when NO vertical
// tag is present (=> start the internal classification chase). Never substring
// (so "TREE_CODE_RESEARCH" does NOT match). Umbrella tag -> 'general'.
const TAGMAP = {
  'tree': 'tree',
  'roofing': 'roofing',
  'landscaping': 'landscaping',
  'construction': 'construction',
  'united services northwest': 'general',
};
function resolveVertical() {
  for (const t of tags) {
    const tt = String(t || '').trim().toLowerCase();
    if (Object.prototype.hasOwnProperty.call(TAGMAP, tt)) return TAGMAP[tt];
  }
  return null;
}
const vertical = resolveVertical();
const route = vertical ? 'tagged' : 'untagged';

const senderMap = {
  tree:         'sales@washingtontreeservices.com',
  roofing:      'sales@washingtonroofing.com',
  landscaping:  'sales@washingtonlandscaping.com',
  construction: 'sales@washingtonconstruction.com',
  general:      'sales@unitedservicesnorthwest.com',
};
const would_send_from = senderMap[vertical] || senderMap.general;

const SHADOW = false;
const would_send_to = customer_email;                               // real recipient (banner only)
const send_target   = SHADOW ? 'neil@neilghuman.com' : customer_email;

return [{ json: {
  customer_id,
  customer_first,
  customer_last,
  customer_email,
  customer_phone,
  lead_source,
  tags,
  vertical,                                   // may be null (untagged)
  route,                                      // 'tagged' | 'untagged'
  notification_type: route === 'tagged' ? 'welcome' : 'classify',
  would_send: false,                          // receiver no longer sends
  would_send_from,
  would_send_to,
  send_target,
  shadow: SHADOW,
  event: ev,
  occurred_at: body.event_occurred_at || null,
  company_id: (body.company_id != null) ? String(body.company_id) : null,
  raw_payload: body,
  n8n_workflow: 'HCP Customer Events',
  n8n_execution_id: $execution.id,
}}];

