const root = $('HCP Webhook').item.json;
const body = root.body || root;
const ev = body.event || '(unknown)';
const company_id  = (body.company_id != null) ? String(body.company_id) : '';
const occurred_at = body.event_occurred_at || '';

// Surface a primary entity + id for the subject line, when present.
const entityKeys = ['estimate', 'job', 'invoice', 'lead', 'customer', 'appointment'];
let entity = '', entityId = '';
for (const k of entityKeys) {
  if (body[k] && typeof body[k] === 'object') {
    entity = k;
    entityId = (body[k].id != null) ? String(body[k].id) : '';
    break;
  }
}

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let pretty = JSON.stringify(body, null, 2);
if (pretty.length > 50000) pretty = pretty.slice(0, 50000) + '\n... (truncated)';

const emailSubject = '[HCP Event] ' + ev + (entity ? (' \u2014 ' + entity + (entityId ? ' ' + entityId : '')) : '');

const rows = [
  ['Event', ev],
  ['Entity', entity ? (entity + (entityId ? ' ' + entityId : '')) : '(n/a)'],
  ['Occurred at', occurred_at],
  ['Company', company_id],
  ['n8n execution', String($execution.id)],
];
const rowHtml = rows.map(r =>
  '<tr><td style="padding:4px 12px 4px 0;color:#6b7280;font-weight:600;white-space:nowrap;">' + esc(r[0]) +
  '</td><td style="padding:4px 0;color:#111827;">' + esc(r[1]) + '</td></tr>'
).join('');

const emailHtml =
  '<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#111827;">' +
  '<h2 style="margin:0 0 12px;font-size:18px;">HCP webhook captured</h2>' +
  '<table style="border-collapse:collapse;margin-bottom:16px;">' + rowHtml + '</table>' +
  '<div style="color:#6b7280;font-size:12px;margin-bottom:6px;">Full payload:</div>' +
  '<pre style="background:#f3f4f6;border:1px solid #e5e7eb;border-radius:6px;padding:12px;' +
  'font-size:12px;line-height:1.4;overflow:auto;white-space:pre-wrap;word-break:break-word;">' +
  esc(pretty) + '</pre></div>';

return [{ json: { event: ev, entity, entityId, emailSubject, emailHtml } }];
